script = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
# Step 1 lookup formulas: Data sheet codes in D21:D38, year headers H4:L4, values H21:L38.
for r1, r2 in [(12,17), (19,24), (26,31)]:
    for r in range(r1, r2+1):
        for c in range(8,13):
            col=get_column_letter(c)
            ws.cell(r,c).value = f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
# Step 2 net renewable balance: rows 35-40 correspond to 12-17, 19-24, 26-31 respectively.
for out_r, ren_r, grid_r, base_r in zip(range(35,41), range(12,18), range(19,25), range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(out_r,c).value = f'=({col}{ren_r}-{col}{grid_r})/{col}{base_r}*100'
# Step 2 stats by actual labels in E42:E47.
stat_formula = {
    'Minimum': 'MIN',
    'Maximum': 'MAX',
    'Median': 'MEDIAN',
    'Simple mean': 'AVERAGE',
    '25th percentile': 'PERCENTILE',
    '75th percentile': 'PERCENTILE',
}
for r in range(42,48):
    label=ws.cell(r,5).value
    for c in range(8,13):
        col=get_column_letter(c)
        if label == '25th percentile':
            formula=f'=PERCENTILE({col}$35:{col}$40,0.25)'
        elif label == '75th percentile':
            formula=f'=PERCENTILE({col}$35:{col}$40,0.75)'
        elif label in stat_formula:
            formula=f'={stat_formula[label]}({col}$35:{col}$40)'
        else:
            raise ValueError(f'Unexpected statistic label row {r}: {label!r}')
        ws.cell(r,c).value = formula
# Step 3 weighted mean with SUMPRODUCT.
for c in range(8,13):
    col=get_column_letter(c)
    ws.cell(50,c).value = f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
wb.save(path)
print('Saved', path)
print('Sheets after save:', wb.sheetnames)
print('Sample formulas:')
for coord in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','I43','J44','K45','L46','H47','H50','L50']:
    print(coord, ws[coord].value)
'''
res=terminal('python3 - <<\'PY\'\n'+script+'\nPY', timeout=120, workdir='/root')
print(res['output'])
if res.get('exit_code') != 0:
    print('exit_code', res.get('exit_code'))"}

